Variables (LBo : list (Z * Z)) (cr : credit) (sp r P V E S2 B kx bx : Z) (g : PML.ls_state) (ps : PML.pstate) (eg : eghost).
Variables (fx : FPState) (R : bvmap 5 word) (M : mem) (model : Model) (K : ShapeAlg.TSet).
Variables (p e : Z).
