Lemma PAR : PML.u64 M P PML.VT_PARSER /\ PML.u32 M (P + 8) 1024 /\
  PML.u8 M (P + 12) 0 /\ PML.u8 M (P + 13) 1 /\ PML.u8 M (P + 14) 0 /\ PML.u8 M (P + 15) 1 /\ PML.u8 M (P + 16) 0 /\ PML.u8 M (P + 17) 0 /\ PML.u8 M (P + 18) 0 /\
  L5.lstr_short RSEGS M (P + 24) [] /\ L5.lstr_short RSEGS M (P + 48) [] /\ L5.lstr_short RSEGS M (P + 72) [] /\
