Let LS : hl_segs L = RSEGS := PmLayout.ly_segs L LAY.
Lemma CRS_OKV : forall g1 (rg : SGP.region), In rg (CH.hd_crs G.HDECL) -> SGP.region_vars_lt GT.NF rg = true /\ (forall a : Z, CH2.in_reg E0 rg a -> CH2.sclient L (LBr g1) sp a).
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S00$g1;R+b4!:'i:/L;'f:'c9/LBo;/sp;'f8+b4'cB'i;#1").
