(* [comment removed for export] *)
Lemma view_sound : forall ml cells BLi pe ce pv E' (M1 : mem),
  PNC.view_chk ml cells BLi = Some (pe, ce, pv) -> ml = 0 \/ ml = 1 -> know_ok RSEGS E' M1 cells -> env_agree GT.NF E0 E' -> L5.defined M1 P 272 ->
  BLi = [(pe, ce); (PNC.SBx, PNC.SCAP)] /\ 0 <= uv E' (PB2.pv_nst pv) <= 7 /\
